mapper.select:
SET LOCK_TIMEOUT 10000;
WITH PARTS AS ( SELECT MAX(SPAREPART.SPP_IDX) AS SPP_IDX, SUM(SPAREHISTORY.SPH_INPUT) AS SPH_INPUT, SUM(SPAREHISTORY.SPH_SURIOUT) AS SPH_SURIOUT, SUM(SPAREHISTORY.SPH_JASANOUT) AS SPH_JASANOUT, SPAREPART.SPP_PURCHASE, SPAREPART.SPP_NO, SPAREPART.SPP_NAME, SPAREPART.SPP_GYU, SPAREPART.SPP_YONG, SPAREPART.SPP_PROPER, SPAREPART.SPP_IMAGE, SPAREPART.SPP_BIGO, SPAREPART.FILE_NAME FROM SPAREHISTORY WITH(NOLOCK) RIGHT OUTER JOIN SPAREPART WITH(NOLOCK) ON SPAREHISTORY.SPP_IDX = SPAREPART.SPP_IDX WHERE SPAREPART.SPP_IDX > 0 GROUP BY SPAREPART.SPP_PURCHASE, SPAREPART.SPP_NO, SPAREPART.SPP_NAME, SPAREPART.SPP_GYU, SPAREPART.SPP_YONG, SPAREPART.SPP_PROPER, SPAREPART.SPP_IMAGE, SPAREPART.SPP_BIGO, SPAREPART.FILE_NAME )
SELECT *, SPH_INPUT - SPH_SURIOUT - SPH_JASANOUT AS spp_jaigo FROM PARTS WITH(NOLOCK) ORDER BY SPP_NO DESC

mapper.update:
		SET LOCK_TIMEOUT 10000;
		UPDATE [dbo].[SPAREPART]
		SET [SPP_PURCHASE]	= #{spp_purchase}	
			,[SPP_NO]		= #{spp_no}			
			,[SPP_NAME]		= #{spp_name}		
			,[SPP_GYU]		= #{spp_gyu}		
			,[SPP_YONG]		= #{spp_yong}		
			,[SPP_PROPER]	= #{spp_proper}		
			,[SPP_IMAGE]	= #{spp_image}
			,[SPP_BIGO]		= #{spp_bigo}	

            ,[FILE_NAME] = #{file_name}

	    WHERE SPP_IDX = #{spp_idx}

mapper.delete:
	SET LOCK_TIMEOUT 10000;
    DELETE FROM SPAREPART
    WHERE SPP_IDX = #{spp_idx}

	SET LOCK_TIMEOUT 10000;
    DELETE FROM SPAREHISTORY
    WHERE SPH_IDX = #{sph_idx}
